begin;
do $curate$ declare bid uuid;begin
if exists(select 1 from businesses where website ilike '%luminateelectric.com%' or lower(name)=lower('Luminate Electric') or regexp_replace(coalesce(phone,''),'[^0-9]','','g') like '%5103030655') then raise exception 'Duplicate requires review';end if;
insert into businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('Luminate Electric','Home Services','Lathrop',null,'(510) 303-0655','https://www.luminateelectric.com/','Lathrop-based provider advertising residential, commercial and industrial electrical work, including panel, lighting and EV-charger services. Its official Central Valley service-area section explicitly names Mountain House, Tracy, Lathrop and Manteca. Confirm property eligibility, job scope, quote, required credentials and current appointment availability directly; a public visitor office is not established here.','approved',true,false,null,0,'editorial_first_party','https://www.luminateelectric.com/service-areas','first_party_website_desk_check',now()) returning id into bid;
insert into listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,'https://www.luminateelectric.com/service-areas',array['identity','website','public phone','advertised electrical services','explicit named service cities'],array['Mountain House','Tracy','Lathrop','Manteca'],array['electrical services','electrical repairs','EV charger installation'],'Official website information checked November 8, 2026: identity, public phone, advertised electrical services and individually named service cities. No owner confirmation, independent license/insurance/quality/safety check, photos, price, appointment or emergency-response endorsement. No visitor-office address established. Sources: https://www.luminateelectric.com/ https://www.luminateelectric.com/service-areas');
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,'{"name": "Luminate Electric", "city": "Lathrop", "phone": "(510) 303-0655", "website": "https://www.luminateelectric.com/", "source_url": "https://www.luminateelectric.com/service-areas", "areas": ["Mountain House", "Tracy", "Lathrop", "Manteca"], "description": "Lathrop-based provider advertising residential, commercial and industrial electrical work, including panel, lighting and EV-charger services. Its official Central Valley service-area section explicitly names Mountain House, Tracy, Lathrop and Manteca. Confirm property eligibility, job scope, quote, required credentials and current appointment availability directly; a public visitor office is not established here."}'::jsonb,'Explicit four-city electrical service coverage','https://www.luminateelectric.com/service-areas');end $curate$;
